# Surah Luqman (chapter 31) — part 4: ayat 31-34 (IDs 3500-3503)
SURAH = 31

ENTRIES = {
3500: (
"کیا تم نہیں دیکھتے کہ جہاز سمندر میں اللہ کی نعمت سے چلتے ہیں تاکہ وہ تمہیں اپنی آیات دکھائے — بے شک اس میں ہر صابر و شاکر کے لیے آیات ہیں",
"""۱۔ جہاز — اللہ کی نعمت؛ آیات؛ صبر و شکر۔
۲۔ ’’أَلَمْ تَرَ أَنَّ الْفُلْكَ تَجْرِي فِي الْبَحْرِ بِنِعْمَتِ اللَّهِ لِيُرِيَكُم مِّنْ آيَاتِهِ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ‘‘ — کیا تم نہیں دیکھتے کہ جہاز سمندر میں اللہ کی نعمت سے چلتے ہیں تاکہ وہ تمہیں اپنی آیات دکھائے — بے شک اس میں ہر صابر و شاکر کے لیے آیات ہیں — یعنی کیا تم نہیں دیکھتے کہ جہاز سمندر میں اللہ کی نعمت سے چلتے ہیں تاکہ وہ تمہیں اپنی آیات دکھائے بے شک اس میں ہر صابر و شاکر کے لیے آیات ہیں۔
۳۔ عملی سبق: جہاز اور سمندر کی قدرت دیکھو؛ صبر و شکر کرو؛ اللہ سے ڈرو۔"""
),
3501: (
"اور جب انہیں سائبانوں کی طرح موج ڈھانپ لیتی ہے تو وہ اللہ کو خالص دین کے ساتھ پکارتے ہیں — پھر جب وہ انہیں خشکی کی طرف نجات دیتا ہے تو ان میں سے کچھ معتدل رہتے ہیں — اور ہماری آیات کا انکار صرف ہر دھوکے باز ناشکرے ہی کرتے ہیں",
"""۱۔ طوفان — خالص پکار؛ اعتدال؛ دھوکے باز ناشکرے۔
۲۔ ’’وَإِذَا غَشِيَهُم مَّوْجٌ كَالظُّلَلِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ فَمِنْهُم مُّقْتَصِدٌ وَمَا يَجْحَدُ بِآيَاتِنَا إِلَّا كُلُّ خَتَّارٍ كَفُورٍ‘‘ — اور جب انہیں سائبانوں کی طرح موج ڈھانپ لیتی ہے تو وہ اللہ کو خالص دین کے ساتھ پکارتے ہیں — پھر جب وہ انہیں خشکی کی طرف نجات دیتا ہے تو ان میں سے کچھ معتدل رہتے ہیں — اور ہماری آیات کا انکار صرف ہر دھوکے باز ناشکرے ہی کرتے ہیں — یعنی اور جب انہیں سائبانوں کی طرح موج ڈھانپ لیتی ہے تو وہ اللہ کو خالص دین کے ساتھ پکارتے ہیں پھر جب وہ انہیں خشکی کی طرف نجات دیتا ہے تو ان میں سے کچھ معتدل رہتے ہیں اور ہماری آیات کا انکار صرف ہر دھوکے باز ناشکرے ہی کرتے ہیں۔
۳۔ عملی سبق: ہر حال میں اللہ کو پکارو؛ دھوکے بازی اور ناشکری سے بچو؛ اس سے ڈرو۔"""
),
3502: (
"اے لوگو اپنے رب سے ڈرو — اور اس دن سے خوف کھاؤ جس میں نہ باپ بیٹے کی طرف سے بدلہ دیا جائے گا اور نہ بیٹا باپ کی طرف سے کچھ بدلہ دے گا — بے شک اللہ کا وعدہ سچا ہے — پس تمہیں دنیا کی زندگی دھوکا نہ دے — اور نہ (شیطان) تمہیں اللہ کے بارے میں دھوکا دے",
"""۱۔ تقویٰ — قیامت؛ کوئی شفاعت نہیں؛ دھوکے سے بچنا؛ اللہ کا وعدہ۔
۲۔ ’’يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا لَّا يَجْزِي وَالِدٌ عَن وَلَدِهِ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِ شَيْئًا إِنَّ وَعْدَ اللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ الْحَيَاۃُ الدُّنْيَا وَلَا يَغُرَّنَّكُم بِاللَّهِ الْغَرُورُ‘‘ — اے لوگو اپنے رب سے ڈرو — اور اس دن سے خوف کھاؤ جس میں نہ باپ بیٹے کی طرف سے بدلہ دیا جائے گا اور نہ بیٹا باپ کی طرف سے کچھ بدلہ دے گا — بے شک اللہ کا وعدہ سچا ہے — پس تمہیں دنیا کی زندگی دھوکا نہ دے — اور نہ (شیطان) تمہیں اللہ کے بارے میں دھوکا دے — یعنی اے لوگو اپنے رب سے ڈرو اور اس دن سے خوف کھاؤ جس میں نہ باپ بیٹے کی طرف سے بدلہ دیا جائے گا اور نہ بیٹا باپ کی طرف سے کچھ بدلہ دے گا بے شک اللہ کا وعدہ سچا ہے پس تمہیں دنیا کی زندگی دھوکا نہ دے اور نہ شیطان تمہیں اللہ کے بارے میں دھوکا دے۔
۳۔ عملی سبق: تقویٰ اختیار کرو؛ دنیا کے دھوکے سے بچو؛ قیامت کی تیاری کرو۔"""
),
3503: (
"بے شک اللہ کے پاس قیامت کا علم ہے — اور وہی بارش نازل کرتا ہے — اور وہ جانتا ہے جو کچھ رحموں میں ہے — اور کوئی جان نہیں جانتی کہ کل کیا کمائے گی — اور کوئی جان نہیں جانتی کہ کس سرزمین میں مرے گی — بے شک اللہ علیم و خبیر ہے",
"""۱۔ اللہ کے خمسہ غیب — قیامت؛ بارش؛ ارحام؛ کل کی کمائی؛ موت کی جگہ؛ علیم و خبیر۔
۲۔ ’’إِنَّ اللَّهَ عِندَهُ عِلْمُ السَّاعَۃِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَّاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ‘‘ — بے شک اللہ کے پاس قیامت کا علم ہے — اور وہی بارش نازل کرتا ہے — اور وہ جانتا ہے جو کچھ رحموں میں ہے — اور کوئی جان نہیں جانتی کہ کل کیا کمائے گی — اور کوئی جان نہیں جانتی کہ کس سرزمین میں مرے گی — بے شک اللہ علیم و خبیر ہے — یعنی بے شک اللہ کے پاس قیامت کا علم ہے اور وہی بارش نازل کرتا ہے اور وہ جانتا ہے جو کچھ رحموں میں ہے اور کوئی جان نہیں جانتی کہ کل کیا کمائے گی اور کوئی جان نہیں جانتی کہ کس سرزمین میں مرے گی بے شک اللہ علیم و خبیر ہے۔
۳۔ عملی سبق: غیب صرف اللہ جانتا ہے؛ اس سے ڈرو؛ نیکیاں کماؤ۔"""
),
}
